def check_records(test_cases):
    results = []
    for case in test_cases:
        n, stats = case
        is_valid = True
        for i in range(n):
            plays, clears = stats[i]
            if clears > plays:
                is_valid = False
                break
            if i > 0:
                prev_plays, prev_clears = stats[i-1]
                if plays < prev_plays or clears < prev_clears or (plays - prev_plays) < (clears - prev_clears):
                    is_valid = False
                    break
                if plays == prev_plays and clears > prev_clears and (clears - prev_clears) > 1:
                    is_valid = False
                    break
        results.append("YES" if is_valid else "NO")
    return results
